/**
 * Shape of public/data/portfolio.json (the `data` payload) as the shared content
 * model reads it. Everything is optional: the file is regenerated by "Reload by
 * AI" and fields come and go. Templates never read this directly; they read
 * PortfolioContent from build.ts.
 */

export interface RawExperience {
  company?: string;
  title?: string;
  role?: string;
  dates?: string;
  duration?: string;
  location?: string;
  link?: string;
  github?: string;
  achievements?: string[];
  accomplishments?: string[];
  description?: string;
}

export interface RawProject {
  id?: string;
  title?: string;
  name?: string;
  description?: string;
  technologies?: string[];
  github?: string;
  githubUrl?: string;
  demo?: string;
  demoUrl?: string;
  url?: string;
  featured?: boolean;
  stars?: number | null;
  forks?: number | null;
  commits?: number | null;
  topics?: string[];
  source?: string;
  role?: string;
  status?: string;
  showcaseRepo?: string;
  timeline?: { created_at?: string; updated_at?: string; pushed_at?: string };
}

export interface RawEducation {
  institution?: string;
  degree?: string;
  dates?: string;
  cgpa?: string;
  gpa?: string;
}

export interface RawLeadership {
  role?: string;
  organization?: string;
  duration?: string;
  description?: string;
}

export interface RawGithubRepo {
  name?: string;
  full_name?: string;
  html_url?: string;
  description?: string | null;
  homepage?: string | null;
  stargazers_count?: number;
  forks_count?: number;
  language?: string | null;
  topics?: string[];
  commits?: number | null;
  updated_at?: string;
  created_at?: string;
  pushed_at?: string;
}

export interface RawGithubData {
  user?: {
    login?: string;
    name?: string;
    html_url?: string;
    avatar_url?: string;
    bio?: string | null;
    created_at?: string;
    followers?: number;
    following?: number;
    public_repos?: number;
  };
  repositories?: RawGithubRepo[];
  contributions?: Array<{ date?: string; count?: number; level?: number }>;
  languageStats?: Record<string, number> | Array<{ name?: string; language?: string; percentage?: number }>;
  recentActivity?: Array<{ created_at?: string; type?: string; repo?: string; payload?: Record<string, unknown> }>;
}

export interface RawPortfolio {
  personalInfo?: {
    name?: string;
    title?: string;
    summary?: string;
    availability?: string;
    graduationYear?: number;
    email?: string;
    collegeEmail?: string;
    phone?: string;
    location?: string;
  };
  experience?: RawExperience[];
  education?: RawEducation[];
  projects?: RawProject[];
  skills?: unknown;
  socialLinks?: Record<string, string | undefined>;
  resumeUrl?: string;
  githubStats?: {
    totalPublicRepos?: number;
    totalStars?: number;
    totalForks?: number;
    totalCommits?: number | string;
    totalContributions?: number;
    contributionsAsOf?: string;
    contributionsSince?: number;
    featuredRepos?: number;
  };
  githubData?: RawGithubData;
  achievements?: string[];
  leadership?: RawLeadership[];
  coursework?: Array<{ course?: string; grade?: string | null }>;
  insights?: unknown;
  techStack?: unknown;
  lastUpdated?: string | Date;
}
